<?php get_header(); ?><main class="site-main"><header class="archive-heading"><p class="eyebrow">Chuyên mục</p><h1><?php single_cat_title(); ?></h1><?php if ( category_description() ) : ?><div class="archive-description"><?php echo wp_kses_post( category_description() ); ?></div><?php endif; ?></header><?php if ( have_posts() ) : ?><div class="post-grid"><?php while ( have_posts() ) : the_post(); get_template_part( 'template-parts/post', 'card' ); endwhile; ?></div><?php the_posts_pagination( array( 'screen_reader_text' => 'Điều hướng bài viết', 'prev_text' => 'Bài trước', 'next_text' => 'Bài tiếp theo' ) ); else : ?><div class="empty-state"><h2>Chưa có bài viết</h2><p>Chuyên mục này chưa có nội dung.</p></div><?php endif; ?></main><?php get_footer(); ?>
